+    const v = {};
+    decl.forEach((d) => { v[d.id] = d.default; });
+    try {
+      const o = window.__hyperframes && window.__hyperframes.getVariables && window.__hyperframes.getVariables();
+      if (o) Object.assign(v, o);
+    } catch (e) {}
+    return v;
+  };
